<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $status=WPRaffle_Theme_Control_Center::system_status(); $checks=WPRaffle_Theme_Control_Center::readiness(); ?>
<section class="wpr-panel"><div class="wprt-card-heading"><div><span class="dashicons dashicons-dashboard"></span><h2><?php esc_html_e('System Status','wpraffle-theme'); ?></h2></div></div><p class="wpr-panel-intro"><?php esc_html_e('A quick health check for the environment WPRaffle Theme depends on.','wpraffle-theme'); ?></p><div class="wprt-status-table"><?php foreach($status as $row): ?><div class="wprt-status-row"><span class="dashicons dashicons-<?php echo $row['ok']?'yes-alt':'warning'; ?>"></span><strong><?php echo esc_html($row['label']); ?></strong><code><?php echo esc_html($row['value']); ?></code></div><?php endforeach; ?></div></section>
<section class="wpr-panel"><div class="wprt-card-heading"><div><span class="dashicons dashicons-yes-alt"></span><h2><?php esc_html_e('Site readiness','wpraffle-theme'); ?></h2></div></div><div class="wprt-check-list"><?php foreach($checks as $check): ?><div class="wprt-check <?php echo $check['ok']?'is-ok':'is-warning'; ?>"><span class="dashicons dashicons-<?php echo $check['ok']?'yes-alt':'warning'; ?>"></span><div><strong><?php echo esc_html($check['label']); ?></strong><small><?php echo esc_html($check['hint']); ?></small></div></div><?php endforeach; ?></div></section>
<section class="wpr-panel">
<div class="wprt-card-heading"><div><span class="dashicons dashicons-media-text"></span><h2><?php esc_html_e('Support Report','wpraffle-theme'); ?></h2></div></div>
<p><?php esc_html_e('Download a plain-text environment and readiness report that can be attached to a support issue without exposing passwords or private customer data.','wpraffle-theme'); ?></p>
<form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="wprt_download_system_report"><?php wp_nonce_field('wprt_download_system_report'); ?><button class="button"><?php esc_html_e('Download System Report','wpraffle-theme'); ?></button></form>
</section>
